const phone='212670779271';const messages={manager:'Hello, I would like to chat with an OTT Provider reseller manager.',demo:'Hello, I would like demo access for an OTT Provider reseller panel.','credits-100':'Hello, I would like current information and pricing for the 100 Credits reseller package.','credits-250':'Hello, I would like current information and pricing for the 250 Credits reseller package.','credits-500':'Hello, I would like wholesale information and pricing for the 500+ Credits reseller package.'};document.querySelectorAll('.wa').forEach(link=>link.href=`https://wa.me/${phone}?text=${encodeURIComponent(messages[link.dataset.message]||messages.manager)}`);
